#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "rms_norm_tiling.h"

extern "C" void rms_norm_do_fp32(uint32_t, void*, uint8_t*, uint8_t*, uint8_t*);
extern "C" void rms_norm_do_fp16(uint32_t, void*, uint8_t*, uint8_t*, uint8_t*);
extern "C" void rms_norm_do_bf16(uint32_t, void*, uint8_t*, uint8_t*, uint8_t*);

namespace rms_norm_ext {
using LaunchFn = void (*)(uint32_t, void*, uint8_t*, uint8_t*, uint8_t*);

pybind11::tuple run_rms_norm(const at::Tensor &x, double eps = 1e-6) {
    TORCH_CHECK(x.dim() == 2, "x must be [M, N]");
    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf || x.scalar_type() == at::kBFloat16, "unsupported dtype");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    const auto m = static_cast<int32_t>(x.sizes()[0]), n = static_cast<int32_t>(x.sizes()[1]);
    const int32_t mNum = (m + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    const int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, mNum);
    const int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
    at::Tensor y = at::empty_like(x);
    at::Tensor tilingCpu = at::empty({static_cast<long>(sizeof(RmsNormKernelTiling))}, at::device(at::kCPU).dtype(at::kByte));
    auto *t = reinterpret_cast<RmsNormKernelTiling *>(tilingCpu.data_ptr());
    t->M = m; t->N = n; t->blockM = DEFAULT_BLOCK_M; t->usedCoreNum = usedCoreNum; t->tasksPerCore = tasksPerCore;
    t->eps = static_cast<float>(eps); t->invN = 1.0f / static_cast<float>(n);
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);
    LaunchFn launch = nullptr;
    if (x.scalar_type() == at::kFloat) launch = rms_norm_do_fp32;
    else if (x.scalar_type() == at::kHalf) launch = rms_norm_do_fp16;
    else if (x.scalar_type() == at::kBFloat16) launch = rms_norm_do_bf16;
    else TORCH_CHECK(false, "unsupported dtype");
    launch(usedCoreNum, aclStream,
        static_cast<uint8_t *>(const_cast<void *>(x.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(y.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(tilingNpu.storage().data())));
    return pybind11::make_tuple(y);
}
}
PYBIND11_MODULE(_rms_norm_ext, m) { m.def("run_rms_norm", &rms_norm_ext::run_rms_norm, ""); }

