extern "C" __global__ __aicore__ void rms_norm_custom_fp32(GM_ADDR x, GM_ADDR y, GM_ADDR tiling) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe pipe;
    RmsNormKernel<float> kernel; kernel.Init(x, y, tiling, &pipe); kernel.Process();
}
