#pragma once
#ifndef RMS_NORM_KERNEL_H
#define RMS_NORM_KERNEL_H
#include <cmath>
#include "kernel_operator.h"
#include "kernel_common.h"
#include "rms_norm_tiling.h"

template <typename dataType>
class RmsNormKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), tiling_.M * tiling_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), tiling_.M * tiling_.N);
        if ASCEND_IS_AIV {
            pipe_ = pipe;
            subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(xInQueue_, 1, tiling_.N * sizeof(dataType));
            pipe_->InitBuffer(yOutQueue_, 1, tiling_.N * sizeof(dataType));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe_->InitBuffer(castBuf_, tiling_.N * sizeof(float));
            }
            pipe_->InitBuffer(computeBuf_, tiling_.N * sizeof(float));
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();
            for (int localIdx = 0; localIdx < tiling_.tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tiling_.tasksPerCore + localIdx;
                if (bx >= BlockCount()) continue;
                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * tiling_.blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < tiling_.M) ProcessRow(rowIdx);
                }
            }
        }
    }

private:
    __aicore__ inline int32_t BlockCount() const { return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM; }

    __aicore__ inline void CopyIn(int32_t rowIdx) {
        xInQueue_.AllocTensor<dataType>(xInLocal_);
        AscendC::DataCopy(xInLocal_, xGM_[rowIdx * tiling_.N], static_cast<uint32_t>(tiling_.N));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOut(int32_t rowIdx) {
        yOutQueue_.DeQue<dataType>(yOutLocal_);
        AscendC::DataCopy(yGM_[rowIdx * tiling_.N], yOutLocal_, static_cast<uint32_t>(tiling_.N));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeRow(int32_t rowIdx) {
        xInQueue_.DeQue<dataType>(xInLocal_);
        yOutQueue_.AllocTensor<dataType>(yOutLocal_);
        AscendC::LocalTensor<float> addFp32 = computeBuf_.Get<float>();

        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::LocalTensor<float> xFp32 = xInLocal_.template ReinterpretCast<float>();
            float sumSqVal = 0.0f;
            for (int32_t i = 0; i < tiling_.N; ++i) { float v = xFp32(i); sumSqVal += v * v; }
            float invRms = 1.0f / sqrt(sumSqVal * tiling_.invN + tiling_.eps);
            AscendC::LocalTensor<float> yFp32 = yOutLocal_.template ReinterpretCast<float>();
            AscendC::Muls(yFp32, xFp32, invRms, tiling_.N);
        } else {
            AscendC::LocalTensor<float> xFp32 = castBuf_.Get<float>();
            AscendC::Cast(xFp32, xInLocal_, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
            float sumSqVal = 0.0f;
            for (int32_t i = 0; i < tiling_.N; ++i) { float v = xFp32(i); sumSqVal += v * v; }
            float invRms = 1.0f / sqrt(sumSqVal * tiling_.invN + tiling_.eps);
            AscendC::Muls(addFp32, xFp32, invRms, tiling_.N);
            AscendC::Cast(yOutLocal_, addFp32, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
        }
        yOutQueue_.EnQue(yOutLocal_);
        xInQueue_.FreeTensor(xInLocal_);
    }

    __aicore__ inline void ProcessRow(int rowIdx) { CopyIn(rowIdx); ComputeRow(rowIdx); CopyOut(rowIdx); }

private:
    RmsNormKernelTiling tiling_{}; AscendC::TPipe *pipe_{nullptr}; int subBlockRows_{0};
    AscendC::GlobalTensor<dataType> xGM_; AscendC::GlobalTensor<dataType> yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, 0> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf_;
    AscendC::LocalTensor<dataType> xInLocal_; AscendC::LocalTensor<dataType> yOutLocal_;
};
#endif
